"use strict";const t=require("../common/vendor.js");exports.parseLaunchShopInvite=function(t){if(!t)return null;if(t.inviteToken)return{token:String(t.inviteToken).trim()};if(t.shopCode)return{shopCode:String(t.shopCode).trim()};if(t.scene){const n=decodeURIComponent(String(t.scene));return n.startsWith("t")&&n.length>1?{token:n.slice(1).trim()}:n.startsWith("s=")?{shopCode:n.slice(2).trim()}:{shopCode:n.trim()}}return null},exports.parseOrderTokenFromScan=function(t){const n=(t||"").trim().match(/^MOBI:ORDER:(.+)$/i);return n?n[1].trim():""},exports.parsePayTokenFromScan=function(t){const n=(t||"").trim().match(/^MOBI:PAY:(.+)$/i);return n?n[1].trim():""},exports.parseShopCodeFromScan=function(t){const n=(t||"").trim();if(!n)return"";if(n.match(/^MOBI:SHOP:INV:(.+)$/i))return"";const e=n.match(/^MOBI:SHOP:(.+)$/i);return e?e[1].trim():(/^[A-Za-z0-9]{6,16}$/.test(n),n)},exports.parseShopInviteFromScan=function(t){const n=(t||"").trim();if(!n)return"";const e=n.match(/^MOBI:SHOP:INV:(.+)$/i);return e?e[1].trim():""},exports.parseStaffInviteTokenFromScan=function(t){const n=(t||"").trim().match(/^MOBI:STAFF:INV:(.+)$/i);return n?n[1].trim():""},exports.savePendingShopCode=function(n){if(n)try{t.index.setStorageSync("pending_shop_code",n)}catch{}},exports.savePendingShopInvite=function(n){if(n)try{t.index.setStorageSync("pending_shop_invite",n)}catch{}},exports.takePendingShopCode=function(){try{const n=t.index.getStorageSync("pending_shop_code");return n&&t.index.removeStorageSync("pending_shop_code"),n?String(n).trim():""}catch{return""}},exports.takePendingShopInvite=function(){try{const n=t.index.getStorageSync("pending_shop_invite");return n&&t.index.removeStorageSync("pending_shop_invite"),n?String(n).trim():""}catch{return""}};
